-- Dữ liệu gốc Anyhome — sinh tự động bởi scripts/generate-seed.ts, đừng sửa tay.
-- Chạy SAU supabase/schema.sql. Chạy lại sẽ ghi đè các bản ghi mẫu (theo id).

begin;

on conflict (id) do update set slug = excluded.slug, title = excluded.title, category = excluded.category, location = excluded.location, scale = excluded.scale, area = excluded.area, year = excluded.year, client = excluded.client, scope = excluded.scope, summary = excluded.summary, cover = excluded.cover, gallery = excluded.gallery, before_after = excluded.before_after, featured = excluded.featured, status = excluded.status, created_at = excluded.created_at;

on conflict (id) do update set slug = excluded.slug, title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, cover = excluded.cover, category = excluded.category, tags = excluded.tags, author = excluded.author, status = excluded.status, published_at = excluded.published_at, updated_at = excluded.updated_at;

on conflict (id) do update set name = excluded.name, "group" = excluded."group", spec = excluded.spec, quantity = excluded.quantity, unit = excluded.unit, origin = excluded.origin, image = excluded.image, created_at = excluded.created_at;

on conflict (id) do update set name = excluded.name, phone = excluded.phone, email = excluded.email, project_type = excluded.project_type, area = excluded.area, budget = excluded.budget, message = excluded.message, status = excluded.status, created_at = excluded.created_at;

on conflict (id) do nothing;

commit;
